from checkout.cart import make_cart
from checkout.orders import build_gift_order, place_order


ADDRESS = {"name": "Ana Recipient", "line1": "1 Gift St", "city": "Lisbon", "zip": "1000-001"}
ITEMS = [{"sku": "MUG-1", "price": 25.0, "qty": 2}]


def _gift_cart():
    # positional args: shipping param was renamed between versions
    return make_cart(ITEMS, ADDRESS, True, "Happy birthday!")


def test_build_gift_order_from_make_cart():
    order = build_gift_order("O-1", _gift_cart(), [])
    assert order["ship_to"] == ADDRESS
    assert order["gift_message"] == "Happy birthday!"
    assert order["hide_prices"] is True


def test_place_order_routes_gift_without_keyerror():
    order = place_order("O-2", _gift_cart(), [])
    assert order["ship_to"] == ADDRESS
    assert order["total"] == 50.0
